CREATE DATABASE IF NOT EXISTS access_hospital CHARACTER SET utf8mb4 COLLATE utf8mb4_unicode_ci;
USE access_hospital;
SET FOREIGN_KEY_CHECKS=0;
DROP TABLE IF EXISTS audit_logs,payments,invoice_items,invoices,prescription_items,prescriptions,medications,lab_results,lab_orders,admissions,beds,wards,visits,appointments,contact_messages,patients,staff,services,departments,admins;
SET FOREIGN_KEY_CHECKS=1;
CREATE TABLE admins(id INT UNSIGNED AUTO_INCREMENT PRIMARY KEY,name VARCHAR(120) NOT NULL,email VARCHAR(190) NOT NULL UNIQUE,password_hash VARCHAR(255) NOT NULL,active TINYINT(1) NOT NULL DEFAULT 1,created_at TIMESTAMP DEFAULT CURRENT_TIMESTAMP);
CREATE TABLE departments(id INT UNSIGNED AUTO_INCREMENT PRIMARY KEY,name VARCHAR(150) NOT NULL,description TEXT,active TINYINT(1) NOT NULL DEFAULT 1,created_at TIMESTAMP DEFAULT CURRENT_TIMESTAMP);
CREATE TABLE services(id INT UNSIGNED AUTO_INCREMENT PRIMARY KEY,name VARCHAR(150) NOT NULL,description TEXT,active TINYINT(1) NOT NULL DEFAULT 1,created_at TIMESTAMP DEFAULT CURRENT_TIMESTAMP);
CREATE TABLE staff(id BIGINT UNSIGNED AUTO_INCREMENT PRIMARY KEY,staff_no VARCHAR(40) UNIQUE,full_name VARCHAR(150) NOT NULL,role ENUM('Doctor','Nurse','Midwife','Laboratory','Pharmacist','Administrator','Other') NOT NULL DEFAULT 'Other',department_id INT UNSIGNED NULL,phone VARCHAR(40),email VARCHAR(190),active TINYINT(1) NOT NULL DEFAULT 1,created_at TIMESTAMP DEFAULT CURRENT_TIMESTAMP,FOREIGN KEY(department_id) REFERENCES departments(id) ON DELETE SET NULL);
CREATE TABLE patients(id BIGINT UNSIGNED AUTO_INCREMENT PRIMARY KEY,patient_no VARCHAR(40) NOT NULL UNIQUE,full_name VARCHAR(150) NOT NULL,phone VARCHAR(40),date_of_birth DATE NULL,gender ENUM('Male','Female','Other','Unknown') NOT NULL DEFAULT 'Unknown',address VARCHAR(255),next_of_kin VARCHAR(150),next_of_kin_phone VARCHAR(40),created_at TIMESTAMP DEFAULT CURRENT_TIMESTAMP,INDEX(full_name),INDEX(phone));
CREATE TABLE appointments(id BIGINT UNSIGNED AUTO_INCREMENT PRIMARY KEY,patient_id BIGINT UNSIGNED NULL,patient_name VARCHAR(150) NOT NULL,phone VARCHAR(40) NOT NULL,department_id INT UNSIGNED NULL,appointment_date DATE NOT NULL,appointment_time TIME NULL,reason TEXT,status ENUM('Pending','Confirmed','Completed','Cancelled','No-show') NOT NULL DEFAULT 'Pending',created_at TIMESTAMP DEFAULT CURRENT_TIMESTAMP,FOREIGN KEY(patient_id) REFERENCES patients(id) ON DELETE SET NULL,FOREIGN KEY(department_id) REFERENCES departments(id) ON DELETE SET NULL,INDEX(status,appointment_date));
CREATE TABLE visits(id BIGINT UNSIGNED AUTO_INCREMENT PRIMARY KEY,patient_id BIGINT UNSIGNED NOT NULL,doctor_id BIGINT UNSIGNED NULL,visit_type ENUM('OPD','Emergency','Follow-up','Review') NOT NULL DEFAULT 'OPD',chief_complaint TEXT,diagnosis TEXT,notes TEXT,status ENUM('Open','Closed') NOT NULL DEFAULT 'Open',visit_date DATETIME DEFAULT CURRENT_TIMESTAMP,FOREIGN KEY(patient_id) REFERENCES patients(id) ON DELETE CASCADE,FOREIGN KEY(doctor_id) REFERENCES staff(id) ON DELETE SET NULL,INDEX(visit_date));
CREATE TABLE wards(id INT UNSIGNED AUTO_INCREMENT PRIMARY KEY,name VARCHAR(100) NOT NULL,type ENUM('General','Private','Maternity','Paediatrics','ICU','Other') NOT NULL DEFAULT 'General',capacity INT UNSIGNED NOT NULL DEFAULT 0,active TINYINT(1) NOT NULL DEFAULT 1);
CREATE TABLE beds(id INT UNSIGNED AUTO_INCREMENT PRIMARY KEY,ward_id INT UNSIGNED NOT NULL,bed_no VARCHAR(30) NOT NULL,gender_restriction ENUM('Any','Male','Female') NOT NULL DEFAULT 'Any',status ENUM('Available','Occupied','Maintenance','Reserved') NOT NULL DEFAULT 'Available',UNIQUE(ward_id,bed_no),FOREIGN KEY(ward_id) REFERENCES wards(id) ON DELETE CASCADE);
CREATE TABLE admissions(id BIGINT UNSIGNED AUTO_INCREMENT PRIMARY KEY,patient_id BIGINT UNSIGNED NOT NULL,bed_id INT UNSIGNED NULL,admission_no VARCHAR(40) NOT NULL UNIQUE,admitted_at DATETIME DEFAULT CURRENT_TIMESTAMP,discharged_at DATETIME NULL,reason TEXT,diagnosis TEXT,status ENUM('Admitted','Discharged','Transferred') NOT NULL DEFAULT 'Admitted',FOREIGN KEY(patient_id) REFERENCES patients(id) ON DELETE CASCADE,FOREIGN KEY(bed_id) REFERENCES beds(id) ON DELETE SET NULL,INDEX(status));
CREATE TABLE lab_orders(id BIGINT UNSIGNED AUTO_INCREMENT PRIMARY KEY,patient_id BIGINT UNSIGNED NOT NULL,visit_id BIGINT UNSIGNED NULL,test_name VARCHAR(150) NOT NULL,requested_by BIGINT UNSIGNED NULL,status ENUM('Requested','Collected','Completed','Cancelled') NOT NULL DEFAULT 'Requested',result TEXT,ordered_at DATETIME DEFAULT CURRENT_TIMESTAMP,completed_at DATETIME NULL,FOREIGN KEY(patient_id) REFERENCES patients(id) ON DELETE CASCADE,FOREIGN KEY(visit_id) REFERENCES visits(id) ON DELETE SET NULL,FOREIGN KEY(requested_by) REFERENCES staff(id) ON DELETE SET NULL);
CREATE TABLE medications(id INT UNSIGNED AUTO_INCREMENT PRIMARY KEY,name VARCHAR(150) NOT NULL,unit VARCHAR(50) NOT NULL DEFAULT 'tablet',stock_qty DECIMAL(12,2) NOT NULL DEFAULT 0,unit_price DECIMAL(12,2) NOT NULL DEFAULT 0,reorder_level DECIMAL(12,2) NOT NULL DEFAULT 0,active TINYINT(1) NOT NULL DEFAULT 1);
CREATE TABLE prescriptions(id BIGINT UNSIGNED AUTO_INCREMENT PRIMARY KEY,patient_id BIGINT UNSIGNED NOT NULL,visit_id BIGINT UNSIGNED NULL,prescribed_by BIGINT UNSIGNED NULL,status ENUM('Active','Dispensed','Cancelled') NOT NULL DEFAULT 'Active',instructions TEXT,created_at TIMESTAMP DEFAULT CURRENT_TIMESTAMP,FOREIGN KEY(patient_id) REFERENCES patients(id) ON DELETE CASCADE,FOREIGN KEY(visit_id) REFERENCES visits(id) ON DELETE SET NULL,FOREIGN KEY(prescribed_by) REFERENCES staff(id) ON DELETE SET NULL);
CREATE TABLE prescription_items(id BIGINT UNSIGNED AUTO_INCREMENT PRIMARY KEY,prescription_id BIGINT UNSIGNED NOT NULL,medication_id INT UNSIGNED NOT NULL,dose VARCHAR(100),frequency VARCHAR(100),duration VARCHAR(100),quantity DECIMAL(12,2) NOT NULL DEFAULT 0,FOREIGN KEY(prescription_id) REFERENCES prescriptions(id) ON DELETE CASCADE,FOREIGN KEY(medication_id) REFERENCES medications(id) ON DELETE RESTRICT);
CREATE TABLE invoices(id BIGINT UNSIGNED AUTO_INCREMENT PRIMARY KEY,patient_id BIGINT UNSIGNED NOT NULL,invoice_no VARCHAR(40) NOT NULL UNIQUE,status ENUM('Unpaid','Part-paid','Paid','Cancelled') NOT NULL DEFAULT 'Unpaid',subtotal DECIMAL(12,2) NOT NULL DEFAULT 0,discount DECIMAL(12,2) NOT NULL DEFAULT 0,total DECIMAL(12,2) NOT NULL DEFAULT 0,created_at TIMESTAMP DEFAULT CURRENT_TIMESTAMP,FOREIGN KEY(patient_id) REFERENCES patients(id) ON DELETE CASCADE);
CREATE TABLE invoice_items(id BIGINT UNSIGNED AUTO_INCREMENT PRIMARY KEY,invoice_id BIGINT UNSIGNED NOT NULL,description VARCHAR(255) NOT NULL,quantity DECIMAL(12,2) NOT NULL DEFAULT 1,unit_price DECIMAL(12,2) NOT NULL DEFAULT 0,total DECIMAL(12,2) NOT NULL DEFAULT 0,FOREIGN KEY(invoice_id) REFERENCES invoices(id) ON DELETE CASCADE);
CREATE TABLE payments(id BIGINT UNSIGNED AUTO_INCREMENT PRIMARY KEY,invoice_id BIGINT UNSIGNED NOT NULL,amount DECIMAL(12,2) NOT NULL,method ENUM('Cash','Mobile Money','Bank','Insurance','Other') NOT NULL DEFAULT 'Cash',reference VARCHAR(100),paid_at DATETIME DEFAULT CURRENT_TIMESTAMP,FOREIGN KEY(invoice_id) REFERENCES invoices(id) ON DELETE CASCADE);
CREATE TABLE contact_messages(id BIGINT UNSIGNED AUTO_INCREMENT PRIMARY KEY,name VARCHAR(150) NOT NULL,contact VARCHAR(190) NOT NULL,message TEXT NOT NULL,status ENUM('New','Read') NOT NULL DEFAULT 'New',created_at TIMESTAMP DEFAULT CURRENT_TIMESTAMP);
CREATE TABLE audit_logs(id BIGINT UNSIGNED AUTO_INCREMENT PRIMARY KEY,admin_id INT UNSIGNED NULL,action VARCHAR(100) NOT NULL,entity VARCHAR(100) NOT NULL,entity_id BIGINT UNSIGNED NULL,details TEXT,created_at TIMESTAMP DEFAULT CURRENT_TIMESTAMP,FOREIGN KEY(admin_id) REFERENCES admins(id) ON DELETE SET NULL);
